final class CheckoutService {
    private final Supplier<Boolean> newCheckoutEnabled;

    CheckoutService(Supplier<Boolean> newCheckoutEnabled) {
        this.newCheckoutEnabled = newCheckoutEnabled;
    }

    Receipt checkout(Cart cart) {
        return newCheckoutEnabled.get() ? newFlow(cart) : legacyFlow(cart);
    }
}
